CO_DURATIONS = {"rapide": (480, 615), "moyen": (900, 1155), "reel": (1740, 2250)}


def reading_and_parts(apps, schema_editor):
    ExamFormat = apps.get_model("bank", "ExamFormat")
    FormatSection = apps.get_model("bank", "FormatSection")
    for mode, (old, new) in CO_DURATIONS.items():
        FormatSection.objects.filter(format__mode=mode, section="CO", duration_seconds=old).update(
            duration_seconds=new
        )
    FormatSection.objects.filter(section="CO").update(read_before_seconds=15)
    ExamFormat.objects.filter(mode="moyen").update(allow_part_attempts=True)


